:root {
  --bg: #f7f8fa;
  --fg: #1f2430;
  --muted: #5b6474;
  --accent: #2f5bd7;
  --border: #d8dce4;
  --card: #ffffff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", "Noto Sans JP", sans-serif;
  line-height: 1.8;
  font-size: 16px;
}

.wrap {
  max-width: 760px;
  margin: 0 auto;
  padding: 0 20px;
}

header.site {
  background: var(--card);
  border-bottom: 1px solid var(--border);
  padding: 20px 0;
}

header.site .brand {
  font-weight: 700;
  font-size: 18px;
}

nav.site ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 10px 0 0;
  padding: 0;
}

nav.site a {
  color: var(--accent);
  text-decoration: none;
}

nav.site a:hover,
main a:hover {
  text-decoration: underline;
}

main {
  padding: 32px 0 48px;
}

h1 {
  font-size: 28px;
  line-height: 1.5;
  margin: 0 0 8px;
}

h2 {
  font-size: 21px;
  margin: 32px 0 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}

h3 {
  font-size: 17px;
  margin: 20px 0 4px;
}

p,
li {
  color: var(--fg);
}

.lead {
  color: var(--muted);
  font-size: 17px;
}

main a {
  color: var(--accent);
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px 20px;
  margin: 16px 0;
}

.roles {
  list-style: none;
  padding: 0;
  margin: 16px 0;
  display: grid;
  gap: 12px;
}

.roles li {
  background: var(--card);
  border: 1px solid var(--border);
  border-left: 4px solid var(--accent);
  border-radius: 6px;
  padding: 12px 16px;
}

.steps {
  padding-left: 22px;
}

.steps li {
  margin-bottom: 10px;
}

.note {
  color: var(--muted);
  font-size: 14px;
}

code {
  background: #eceff5;
  border-radius: 4px;
  padding: 1px 5px;
  font-size: 14px;
}

.pagenav {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 40px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

